const seeds=[4401,4402,4403,4404];
function fit(X,Y){const n=X[0].length,A=Array.from({length:n},(_,i)=>Array.from({length:n+1},(_,j)=>j===n?X.reduce((s,x,k)=>s+x[i]*Y[k],0):X.reduce((s,x)=>s+x[i]*x[j],0)+(i===j?1e-8:0)));for(let i=0;i<n;i++){let p=i;for(let j=i+1;j<n;j++)if(Math.abs(A[j][i])>Math.abs(A[p][i]))p=j;[A[i],A[p]]=[A[p],A[i]];const d=A[i][i];if(Math.abs(d)<1e-12)throw Error('singular');for(let k=i;k<=n;k++)A[i][k]/=d;for(let j=0;j<n;j++)if(j!==i){const f=A[j][i];for(let k=i;k<=n;k++)A[j][k]-=f*A[i][k]}}return A.map(a=>a[n])}
const mse=(a,b)=>a.reduce((s,v,i)=>s+(v-b[i])**2,0)/a.length;
function world(seed,kind){let out=[];for(let i=0;i<240;i++){let t=(i+seed%17)/11;let x=Math.sin(t)+.3*Math.cos(t*.39),z=Math.cos(t*.67),noise=.015*Math.sin(i*1.73+seed);let y=kind==='signal'?.25*x+.65*z+(i<120?.2:.8)*x*x+noise: .6*Math.sin(i*1.29+seed*.3)+noise;out.push({x,z,y})}return out}
