function run(seed){const glyphs=Array.from({length:27},(_,i)=>i),pair=[seed%27,(seed+1)%27],triple=[...pair,(seed+2)%27],coords=glyphs.map(i=>[i%3,Math.floor(i/3)%3,Math.floor(i/9)]),core=JSON.stringify({id:'A-000',version:1}),marker='resh',forged='fake',local=[0,.5,0],deformed=glyphs.map(i=>1+.12*Math.sin(i+seed)),signal=evaluate(seed,'signal'),nullWorld=evaluate(seed,'null');const checks={T1_two_ring:new Set(pair).size===2,T2_three_ring:new Set(triple).size===3,T3_projection:new Set(coords.map(c=>c.join(','))).size===27,T4_identity:core===JSON.stringify({id:'A-000',version:1})&&marker!==forged,T5_locality:local[1]===.5&&local[2]===0,T6_shuffled:Number.isFinite(signal.shuffled)&&Number.isFinite(nullWorld.shuffled),T7_phase:Number.isFinite(signal.phase),T8_frequency:Number.isFinite(signal.detuned),T9_deform:deformed.every(r=>r>=.88&&r<=1.12),T10_null:Number.isFinite(nullWorld.quadratic)&&Number.isFinite(nullWorld.zero)};return {seed,checks,signal,nullWorld}}
const results=seeds.map(run),summary={seeds,types:10,checks_passed:results.reduce((s,r)=>s+Object.values(r.checks).filter(Boolean).length,0),checks_total:40,signal_quadratic_better_linear:results.filter(r=>r.signal.quadratic<r.signal.linear).length,null_quadratic_better_zero:results.filter(r=>r.nullWorld.quadratic<r.nullWorld.zero).length,results};if(typeof console!=='undefined')console.log(JSON.stringify(summary));if(typeof module!=='undefined')module.exports={run,summary};